async function T(chars, style, size, color, opts={}){
  const t = figma.createText();
  t.fontName = {family:'Inter',style};
  t.fontSize = size;
  t.characters = chars;
  t.fills = [{type:'SOLID',color}];
  if(opts.width){ t.textAutoResize='HEIGHT'; t.resize(opts.width, t.height); }
  if(opts.align) t.textAlignHorizontal = opts.align;
  if(opts.lh) t.lineHeight = {value:opts.lh, unit:'PIXELS'};
  if(opts.name) t.name = opts.name;
  if(opts.ls) t.letterSpacing = {value:opts.ls, unit:'PIXELS'};
  return t;
}
function F(w,h,fill,opts={}){
  const f = figma.createFrame();
  f.resize(w,h);
  f.fills = fill?[{type:'SOLID',color:fill}]:[];
  if(opts.r!==undefined) f.cornerRadius = opts.r;
  if(opts.name) f.name = opts.name;
  if(opts.layout){ f.layoutMode=opts.layout; f.itemSpacing=opts.gap||0;
    f.paddingLeft=opts.pl||0; f.paddingRight=opts.pr||0; f.paddingTop=opts.pt||0; f.paddingBottom=opts.pb||0;
    if(opts.center){f.primaryAxisAlignItems='CENTER';f.counterAxisAlignItems='CENTER';}
    if(opts.counter) f.counterAxisAlignItems=opts.counter;
    if(opts.primary) f.primaryAxisAlignItems=opts.primary;
    f.primaryAxisSizingMode=opts.fixW?'FIXED':'AUTO'; f.counterAxisSizingMode=opts.fixH?'FIXED':'AUTO';
    if(opts.fixW) f.resize(w, f.height);
  }
  if(opts.stroke){ f.strokes=[{type:'SOLID',color:opts.stroke}]; f.strokeWeight=opts.sw||1; f.strokeAlign='INSIDE'; }
  return f;
}
function icon(id, size, color){
  const main = figma.getNodeById(id);
  const inst = main.createInstance();
  const s = size/main.width;
  inst.resize(size, main.height*s);
  inst.findAll(n=>true).forEach(n=>{
    try{ if(n.fills && n.fills.length && n.fills[0].type==='SOLID') n.fills=[{type:'SOLID',color}]; }catch(e){}
    try{ if(n.strokes && n.strokes.length && n.strokes[0].type==='SOLID') n.strokes=[{type:'SOLID',color}]; }catch(e){}
  });
  return inst;
}
function photo(id, h){
  const main = figma.getNodeById(id);
  const inst = main.createInstance();
  const s = h/main.height;
  inst.resize(main.width*s, h);
  return inst;
}
function stars(count, size){
  const f = F(0,0,null,{name:'Stars '+count, layout:'HORIZONTAL', gap:2, center:true});
  for(let i=0;i<5;i++){
    const st = figma.createStar();
    st.resize(size,size);
    st.fills=[{type:'SOLID',color: i<count?C.star:C.border}];
    st.name='Star '+(i+1);
    f.appendChild(st);
  }
  f.primaryAxisSizingMode='AUTO'; f.counterAxisSizingMode='AUTO';
  return f;
}
