const BTN = figma.getNodeById('1:23');
const TF = figma.getNodeById('1:26');

function button(label, w, h, variant){
  const inst = BTN.createInstance();
  inst.layoutMode='HORIZONTAL';
  inst.primaryAxisAlignItems='CENTER'; inst.counterAxisAlignItems='CENTER';
  inst.resize(w,h);
  inst.primaryAxisSizingMode='FIXED'; inst.counterAxisSizingMode='FIXED';
  inst.cornerRadius=8;
  const t = inst.findOne(n=>n.type==='TEXT');
  t.characters=label;
  if(variant==='secondary'){ inst.fills=[{type:'SOLID',color:C.white}]; inst.strokes=[{type:'SOLID',color:C.border}]; inst.strokeWeight=1; t.fills=[{type:'SOLID',color:C.ink}]; }
  if(variant==='ghost'){ inst.fills=[{type:'SOLID',color:C.surface}]; t.fills=[{type:'SOLID',color:C.ink}]; }
  inst.name='Button · '+label;
  return inst;
}
function textField(placeholder, w, h, opts={}){
  const inst = TF.createInstance();
  inst.resize(w,h);
  inst.primaryAxisSizingMode='FIXED'; inst.counterAxisSizingMode='FIXED';
  inst.cornerRadius = opts.r!==undefined?opts.r:8;
  inst.counterAxisAlignItems='CENTER';
  inst.itemSpacing = 8;
  inst.fills=[{type:'SOLID',color: opts.fill||C.white}];
  if(opts.stroke!==null){ inst.strokes=[{type:'SOLID',color:opts.stroke||C.border}]; inst.strokeWeight=1; }
  const t = inst.findOne(n=>n.type==='TEXT');
  t.characters=placeholder;
  t.fills=[{type:'SOLID',color: opts.color||C.muted}];
  if(opts.size){ t.fontSize=opts.size; }
  inst.name='Text Field · '+placeholder;
  return inst;
}

