const C = { ink:{r:0.102,g:0.102,b:0.122}, gray:{r:0.4,g:0.4,b:0.451} };
function icon(id, size, color){
  const main = figma.getNodeById(id);
  const inst = main.createInstance();
  const s = size/main.width;
  inst.resize(size, main.height*s);
  inst.findAll(n=>true).forEach(n=>{
    try{ if(n.fills && n.fills.length && n.fills[0].type==='SOLID') n.fills=[{type:'SOLID',color}]; }catch(e){}
    try{ if(n.strokes && n.strokes.length && n.strokes[0].type==='SOLID') n.strokes=[{type:'SOLID',color}]; }catch(e){}
  });
  return inst;
}
// replace icon instance inside node `parent` whose current mainComponent id is wrongId, with correctId
function fixIn(root, wrongId, correctId, color){
  const insts = root.findAll(n=>n.type==='INSTANCE' && n.mainComponent && n.mainComponent.id===wrongId);
  let count=0;
  for(const inst of insts){
    const parent = inst.parent;
    const idx = parent.children.indexOf(inst);
    const size = inst.width;
    const wasAbs = inst.layoutPositioning==='ABSOLUTE';
    const x=inst.x, y=inst.y;
    const ni = icon(correctId, size, color||C.ink);
    parent.insertChild(idx, ni);
    if(wasAbs){ ni.layoutPositioning='ABSOLUTE'; ni.x=x; ni.y=y; }
    inst.remove();
    count++;
  }
  return count;
}
