const out=[];
function dump(n,d){
  let s='  '.repeat(d)+n.type+' "'+n.name+'" '+Math.round(n.width)+'x'+Math.round(n.height);
  if(n.layoutMode&&n.layoutMode!=='NONE')s+=' L='+n.layoutMode+' gap='+n.itemSpacing+' pad='+n.paddingLeft+'/'+n.paddingTop+'/'+n.paddingRight+'/'+n.paddingBottom+' pS='+(n.primaryAxisSizingMode||'')+' cS='+(n.counterAxisSizingMode||'');
  if(n.type==='TEXT')s+=' :: '+n.characters.slice(0,30)+' ['+n.fontSize+']';
  if(n.cornerRadius)s+=' r='+n.cornerRadius;
  if(n.fills&&n.fills[0]&&n.fills[0].type==='SOLID'){const c=n.fills[0].color;s+=' #'+[c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');}
  out.push(s);
  if('children' in n)n.children.forEach(c=>dump(c,d+1));
}
dump(figma.getNodeById('10:88'),0);
return out.join('\n');

