const GRAY={r:0.42,g:0.44,b:0.49};
const DARK={r:0.102,g:0.102,b:0.122};
function mkTile(name,title,desc,photoIds){
  const t=figma.createFrame();
  t.name=name;
  t.layoutMode='VERTICAL';
  t.itemSpacing=16;
  t.paddingLeft=24;t.paddingRight=24;t.paddingTop=24;t.paddingBottom=24;
  t.cornerRadius=16;
  t.fills=[{type:'SOLID',color:{r:0.965,g:0.969,b:0.98}}];
  row.appendChild(t);
  t.layoutSizingHorizontal='FILL';
  const ph=figma.createFrame();
  ph.name='Photo';
  ph.layoutMode='HORIZONTAL';
  ph.itemSpacing=8;
  ph.counterAxisAlignItems='CENTER';
  ph.primaryAxisAlignItems='CENTER';
  ph.fills=[];
  ph.resize(280,180);
  t.appendChild(ph);
  ph.layoutSizingHorizontal='FILL';
  ph.layoutSizingVertical='FIXED';
  for(const pid of photoIds){
    const i=figma.getNodeById(pid).createInstance();
    ph.appendChild(i);
    i.resize(Math.round(160/photoIds.length*2),160);
  }
  const ti=figma.createText();
  ti.fontName={family:'Inter',style:'Bold'};
  ti.fontSize=20;
  ti.characters=title;
  ti.fills=[{type:'SOLID',color:DARK}];
  t.appendChild(ti);
  ti.layoutSizingHorizontal='FILL';
  const d=figma.createText();
  d.fontName={family:'Inter',style:'Regular'};
  d.fontSize=14;
  d.characters=desc;
  d.fills=[{type:'SOLID',color:GRAY}];
  d.lineHeight={value:150,unit:'PERCENT'};
  t.appendChild(d);
  d.layoutSizingHorizontal='FILL';
  const b=figma.getNodeById('1:23').createInstance();
  b.name='Shop Now';
  t.appendChild(b);
  b.findOne(n=>n.type==='TEXT').characters='Shop Now';
  return t;
}
