const page = figma.root.children.find(p=>p.name.includes('03'));
await figma.setCurrentPageAsync(page);
const pt=page.findOne(n=>n.name==='Promo Tile');
if(!pt) return 'NOT CREATED';
const out=['Promo Tile '+pt.id+' '+pt.width+'x'+pt.height];
function dump(n,d){
  let s='  '.repeat(d)+n.type+' "'+n.name+'" '+Math.round(n.width)+'x'+Math.round(n.height);
  if(n.type==='TEXT')s+=' :: '+n.characters.slice(0,40).replace(/\n/g,'|');
  out.push(s);
  if('children' in n)n.children.forEach(c=>dump(c,d+1));
}
dump(pt,0);
return out.join('\n');

